// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // We fuzz: a uint256 for v, and an array length nEncoded (as uint256) and a single address to be used as the callee.
    // The property: for any non-empty _tos array (we construct it here) and any callee address that MAY revert on valid calls,
    // the reference contract's transfer() should return (not revert) when all calls to the callee succeed; the mutant that
    // iterates <= may perform an out-of-bounds access and thus revert for some inputs (e.g., when _tos.length = N).
    // We therefore fuzz v, nEncoded and calleeAddr and deploy a Recorder callee that tracks calls. We ensure _tos is non-empty
    // and let the recorder succeed on valid indices. The difference is that the mutant will attempt to call with index N
    // (out of bounds) causing the transfer call to revert; the reference will not.

    function testFuzz_property(uint256 v, uint256 nEncoded, address calleeAddr) public {
        // Keep domain wide but ensure non-empty array length within reasonable bounds to avoid huge gas.
        uint256 n = bound(nEncoded, 1, 10); // admissible domain: 1..10

        // Deploy a Recorder at a deterministic address by using calleeAddr as hint: we ignore calleeAddr's code presence
        // because a fuzzed address is an EOA. Instead we deploy a fresh Recorder and pass its address to c.
        Recorder rec = new Recorder();

        // Build _tos array of length n with distinct addresses (use vm.addr with incrementing keys)
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = vm.addr(uint256(uint160(address(rec))) + i + 1);
        }

        // We will call c.transfer(from, address(rec), tos, v) and observe it does not revert for the reference.
        // The Recorder is implemented to provide the exact transferFrom(address,address,uint256) selector
        // so calls from c succeed; but the mutant that indexes one past end will try to read tos[n] and revert before calling.

        bool ok;
        try c.transfer(address(this), address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all admissible inputs (n >= 1) the reference contract never reverts and thus ok == true.
        // The buggy mutant will produce ok == false for some inputs (notably when it attempts out-of-bounds access), so
        // this assertion will pass on the reference for all fuzz inputs but fail on the mutant for some.
        assertTrue(ok);
    }
}

// Recorder matches the signature transferFrom(address,address,uint256) that C calls via selector.
contract Recorder {
    // Record of last calls (not strictly needed for this test but provides a realistic callee that succeeds).
    event Called(address from, address to, uint256 v);

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
